CREATE TABLE IF NOT EXISTS cao_github_resources (
  namespace TEXT NOT NULL,
  id TEXT NOT NULL,
  etag TEXT NOT NULL,
  upstream_etag TEXT NOT NULL,
  validated_at TIMESTAMPTZ NOT NULL,
  release BOOLEAN NOT NULL,
  full_name TEXT,
  description TEXT,
  html_url TEXT NOT NULL,
  default_branch TEXT,
  stargazers_count BIGINT,
  forks_count BIGINT,
  open_issues_count BIGINT,
  archived BOOLEAN,
  visibility TEXT,
  tag_name TEXT,
  name TEXT,
  published_at TEXT,
  draft BOOLEAN,
  prerelease BOOLEAN,
  PRIMARY KEY (namespace, id),
  CHECK (octet_length(id) <= 512),
  CHECK (octet_length(etag) <= 4096 AND octet_length(upstream_etag) <= 4096)
);

CREATE INDEX IF NOT EXISTS cao_github_resources_expiry ON cao_github_resources (namespace, validated_at, id);

CREATE TABLE IF NOT EXISTS cao_contract (
  digest TEXT NOT NULL,
  PRIMARY KEY (digest)
);

CREATE TABLE IF NOT EXISTS cao_state (
  namespace TEXT NOT NULL,
  revision BIGINT NOT NULL,
  data_revision TEXT NOT NULL,
  evaluated_at TIMESTAMPTZ NOT NULL,
  schema_version BIGINT NOT NULL,
  PRIMARY KEY (namespace)
);

CREATE TABLE IF NOT EXISTS cao_value_publications (
  namespace TEXT NOT NULL,
  packet_id TEXT NOT NULL,
  digest TEXT NOT NULL,
  published_at TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (namespace, packet_id),
  FOREIGN KEY (namespace) REFERENCES cao_state(namespace) ON DELETE CASCADE,
  CHECK (digest ~ '^[a-f0-9]{64}$')
);

CREATE TABLE IF NOT EXISTS cao_quality (
  namespace TEXT NOT NULL,
  collection TEXT NOT NULL,
  availability TEXT NOT NULL,
  completeness TEXT NOT NULL,
  freshness TEXT NOT NULL,
  as_of TIMESTAMPTZ,
  retrieved_at TIMESTAMPTZ,
  PRIMARY KEY (namespace, collection),
  FOREIGN KEY (namespace) REFERENCES cao_state(namespace) ON DELETE CASCADE,
  CHECK (collection IN ('$repositories','$campaigns','$workflows','$runs','$audits','$domains','$evals','$experiments','$evalObservations','$experimentAssignments','$friction','$graders','$graderObservations','$issues','$operationalValueEvidence','$operationalValues','$outcomes','$security-findings','$skills','$tools','$transactions','$workflowValueCollections','work-items')),
  CHECK (availability IN ('available','empty','unavailable')),
  CHECK (completeness IN ('complete','partial','unknown')),
  CHECK (freshness IN ('current','stale','unknown'))
);

CREATE TABLE IF NOT EXISTS cao_repository_lifecycle (
  namespace TEXT NOT NULL,
