  changed_at TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (namespace, id),
  FOREIGN KEY (namespace) REFERENCES cao_state(namespace) ON DELETE CASCADE,
  CHECK (lifecycle IN ('active','archived','deleted'))
);

